"""Data validation — structural (hard fail) and quality (report) checks (spec §3.6)."""
from __future__ import annotations

import numpy as np

from trendbot.strategy.strategy import BarSeries


class StructuralError(ValueError):
    pass


def structural_checks(bar: BarSeries) -> None:
    """Hard-fail structural validation (spec §3.6)."""
    ot = bar.open_time
    if ot.size < 2:
        raise StructuralError("too few bars")
    if np.any(np.diff(ot) <= 0):
        raise StructuralError("open_time not strictly increasing (duplicates or unsorted)")
    if np.any(ot % bar.interval_ms != 0):
        raise StructuralError("open_time not aligned to interval boundary")
    o, h, l, c = bar.open, bar.high, bar.low, bar.close
    if np.any(np.isnan([o, h, l, c])):
        raise StructuralError("NaN in OHLC")
    if np.any(o <= 0) or np.any(h <= 0) or np.any(l <= 0) or np.any(c <= 0):
        raise StructuralError("non-positive prices")
    if np.any(h < np.maximum(o, c) - 1e-9):
        raise StructuralError("high < max(open, close)")
    if np.any(l > np.minimum(o, c) + 1e-9):
        raise StructuralError("low > min(open, close)")
    if np.any(bar.volume < 0):
        raise StructuralError("negative volume")


def quality_report(bar: BarSeries) -> dict:
    """Quality checks — report only, human decides (spec §3.6)."""
    c = bar.close
    o = bar.open
    # bars with |return| > 20%
    rets = c[1:] / c[:-1] - 1.0
    big = int(np.sum(np.abs(rets) > 0.20))
    # continuity: |open_{t+1} - close_t| / close_t
    cont = np.abs(o[1:] - c[:-1]) / c[:-1]
    # zero-volume bars
    zero_vol = int(np.sum(bar.volume == 0))
    return {
        "rows": int(bar.open_time.size),
        "first": int(bar.open_time[0]),
        "last": int(bar.open_time[-1]),
        "bars_abs_return_gt_20pct": big,
        "zero_volume_bars": zero_vol,
        "continuity_median_pct": float(np.median(cont) * 100),
        "continuity_p99_pct": float(np.percentile(cont, 99) * 100),
    }


def cross_source_compare(daily_a: BarSeries, daily_b: BarSeries) -> dict:
    """Compare overlapping daily closes (a vs b) — median abs diff %, days above 0.5%."""
    a_map = {int(t): c for t, c in zip(daily_a.open_time, daily_a.close)}
    b_map = {int(t): c for t, c in zip(daily_b.open_time, daily_b.close)}
    common = sorted(set(a_map) & set(b_map))
    diffs = []
    for t in common:
        if a_map[t] > 0:
            diffs.append(abs(a_map[t] - b_map[t]) / a_map[t] * 100.0)
    diffs = np.array(diffs)
    return {
        "overlapping_days": len(common),
        "median_abs_diff_pct": float(np.median(diffs)) if diffs.size else None,
        "days_above_0.5pct": int(np.sum(diffs > 0.5)) if diffs.size else 0,
    }

